    for ref in REFS:
        n += 1; seed = 9700 + off + n * 7
        text = one(ref, seed); text = text[0].upper() + text[1:]
        if not ('name_' in ref or 'bs_' in ref): text = text.rstrip() + ('' if text.rstrip().endswith('.') else '.') + ' Shown in a clean studio photograph with soft even light.'
